import json

LEVELS = ("debug", "info", "warning", "error")
RESERVED = {"ts", "level", "msg", "run"}
SECRET_FIELDS = {"password", "token", "secret", "api_key", "authorization"}


class RunLog:
    def __init__(self, run_id, clock):
        self.run_id = run_id
        self.clock = clock
        self.lines = []
        self.counts = {level: 0 for level in LEVELS}
        self.first = None
        self.last = None

    def event(self, level, msg, **fields):
        if level not in LEVELS:
            raise ValueError(f"unknown level: {level}")
        clash = RESERVED & set(fields)
        if clash:
            raise ValueError(f"reserved field: {sorted(clash)[0]}")
        now = self.clock()
        record = {"ts": now, "level": level, "msg": msg, "run": self.run_id}
        for name, value in fields.items():
            record[name] = "REDACTED" if name.lower() in SECRET_FIELDS else value
        line = json.dumps(record, ensure_ascii=False)
        self.lines.append(line)
        self.counts[level] += 1
        if self.first is None:
            self.first = now
        self.last = now
        return line

    def summary(self):
        duration = 0 if self.first is None else self.last - self.first
        return {"run": self.run_id, **self.counts, "duration": duration}


def needs_alert(summary, lag, max_lag=3600):
    return summary["error"] > 0 or lag > max_lag

