import json

class Clock:
    def __init__(self, t=100):
        self.t = t
    def __call__(self):
        return self.t

@test("a log line")
def _():
    log = RunLog("r-1", Clock(100))
    line = log.event("info", "invoice created", order="1001", invoice="INV-42")
    check_eq(line, '{"ts": 100, "level": "info", "msg": "invoice created", "run": "r-1", "order": "1001", "invoice": "INV-42"}')
    check_eq(log.lines, [line])

@test("values of any JSON type, and non-ASCII text")
def _():
    log = RunLog("r-2", Clock(5))
    line = log.event("warning", "slow", seconds=2.5, retried=True, ids=[1, 2], note="café")
    check_eq(json.loads(line), {"ts": 5, "level": "warning", "msg": "slow", "run": "r-2", "seconds": 2.5, "retried": True, "ids": [1, 2], "note": "café"})
    check("café" in line)

@test("secrets are redacted")
def _():
    log = RunLog("r-3", Clock())
    line = log.event("error", "auth failed", Token="abc123", api_key="sk_live_x", user="ana")
    check("abc123" not in line and "sk_live_x" not in line)
    check_eq(json.loads(line)["Token"], "REDACTED")
    check_eq(json.loads(line)["user"], "ana")

@test("bad calls")
def _():
    log = RunLog("r-4", Clock())
    check_raises(ValueError, log.event, "fatal", "boom")
    check_raises(ValueError, log.event, "info", "x", run="other")
    check_raises(ValueError, log.event, "info", "x", ts=1)
    check_eq(log.lines, [])

@test("the summary")
def _():
    clock = Clock(1000)
    log = RunLog("r-5", clock)
    check_eq(log.summary(), {"run": "r-5", "debug": 0, "info": 0, "warning": 0, "error": 0, "duration": 0})
    log.event("info", "start")
    clock.t = 1004
    log.event("debug", "page", n=1)
    log.event("error", "dead letter", order="1017")
    clock.t = 1030
    log.event("info", "done")
    check_eq(log.summary(), {"run": "r-5", "debug": 1, "info": 2, "warning": 0, "error": 1, "duration": 30})

@test("when to alert")
def _():
    ok = {"run": "r", "debug": 0, "info": 3, "warning": 2, "error": 0, "duration": 9}
    check(not needs_alert(ok, lag=60))
    check(needs_alert({**ok, "error": 1}, lag=60))
    check(needs_alert(ok, lag=3601))
    check(not needs_alert(ok, lag=3600))
    check(needs_alert(ok, lag=120, max_lag=60))

